export function register(registry: RuntimeRegistry, doc: (name: string) => string) {
  registry.registerNodeType({
    type: 'Generated.Physics.Habitat:leak-co2',
    label: 'CO2 Leak',
    category: 'Physics.Habitat',
    docPath: doc('leak-co2.md'),
    factory: () => new LeakCO2(),
    ports: (instance: RuntimeNode) => {
      const node = instance as LeakCO2;
      return {
        inputPorts: node.inputPorts,
        outputPorts: node.outputPorts,
      };
    },
    signature: {
      purpose: 'CO2 leak source: a mass flow output scaled by a command (0 to 1) from an editable rate, for seals or vents',
      inputs: {
        command: {
          quantity: 'Dimensionless',
          unit: 'ratio',
          description: 'leak opening fraction (0 to 1); 1 when unwired',
        },
      },
      outputs: {
        co2Delta: {
          quantity: 'MassFlow',
          unit: 'kg/s',
          description: 'CO2 mass flow leaving (negative: what leaves the atmosphere)',
        },
        lastLeaked: {
          quantity: 'Mass',
          unit: 'kg',
          description: 'CO2 mass that left on the last tick',
        },
      },
      capabilities: [],
    },
  });
}

import { RuntimeNode, InputPort, OutputPort, Session } from '@spiky-panda/core';

export class LeakCO2 extends RuntimeNode {
  private _rateKgPerS: number = 0.001; // editable: kg/s at full opening
  private _lastLeaked: number = 0; // kg leaked on last tick

  inputPorts: InputPort[] = [
    {
      slot: 'command',
      optional: true,
      type: 'float',
      unit: null,
      kind: 'signal',
      multiplicity: 'single',
    },
  ];

  outputPorts: OutputPort[] = [
    {
      slot: 'co2Delta',
      optional: false,
      type: 'float',
      unit: null,
      kind: 'signal',
      multiplicity: 'single',
    },
    {
      slot: 'lastLeaked',
      optional: false,
      type: 'float',
      unit: null,
      kind: 'signal',
      multiplicity: 'single',
    },
  ];

  @editable
  get rateKgPerS(): number {
    return this._rateKgPerS;
  }

  set rateKgPerS(value: number) {
    this._rateKgPerS = Math.max(0, value);
  }

  @viewable
  get lastLeaked(): number {
    return this._lastLeaked;
  }

  fire(session: Session, t: number): void {
    // Read command input (0 to 1); default to 1 if unwired
    const command = session.readSignal(this, 'command') ?? 1.0;
    const clampedCommand = Math.max(0, Math.min(1, command));

    // Calculate CO2 mass flow leaving (negative: outflow from atmosphere)
    const co2DeltaKgPerS = -clampedCommand * this._rateKgPerS;

    // Calculate mass that left in this tick
    const dt = session.dt ?? 1.0;
    this._lastLeaked = Math.abs(co2DeltaKgPerS) * dt;

    // Publish outputs
    session.writeSignal(this, 'co2Delta', co2DeltaKgPerS);
    session.writeSignal(this, 'lastLeaked', this._lastLeaked);
  }
}

import { test, describe } from 'node:test';
import { strict as assert } from 'node:assert';
import { LeakCO2 } from './leak-co2.node';

describe('LeakCO2', () => {
  test('default rate is 0.001 kg/s', () => {
    const node = new LeakCO2();
    assert.equal(node.rateKgPerS, 0.001);
  });

  test('rate can be set and clamped to non-negative', () => {
    const node = new LeakCO2();
    node.rateKgPerS = 0.005;
    assert.equal(node.rateKgPerS, 0.005);
    node.rateKgPerS = -0.001;
    assert.equal(node.rateKgPerS, 0);
  });

  test('lastLeaked is initially zero', () => {
    const node = new LeakCO2();
    assert.equal(node.lastLeaked, 0);
  });

  test('inputPorts and outputPorts are defined', () => {
    const node = new LeakCO2();
    assert.equal(node.inputPorts.length, 1);
    assert.equal(node.inputPorts[0].slot, 'command');
    assert.equal(node.outputPorts.length, 2);
    assert.equal(node.outputPorts[0].slot, 'co2Delta');
    assert.equal(node.outputPorts[1].slot, 'lastLeaked');
  });
});

